import React, { useState, useEffect, useCallback } from 'react';
import { Link } from 'react-router-dom';
import * as noticeService from '../services/noticeService';
import { useAuth } from '../contexts/AuthContext';
import DeleteNotice from './DeleteNotice';

const ViewNotices = ({ customNotices, onEdit, refreshTrigger }) => {
  const { user, isAdmin, isTeacher } = useAuth();
  const [notices, setNotices] = useState([]);
  const [loading, setLoading] = useState(!customNotices);
  const [selectedNoticeForDelete, setSelectedNoticeForDelete] = useState(null);

  const fetchNotices = useCallback(async () => {
    if (customNotices) {
      setNotices(customNotices);
      setLoading(false);
      return;
    }
    setLoading(true);
    try {
      let data;
      if (user) {
        data = await noticeService.getAllNotices({ size: 50, sortBy: 'publishDate', sortDir: 'desc' });
      } else {
        data = await noticeService.getPublicNotices({ size: 50, sortBy: 'publishDate', sortDir: 'desc' });
      }
      setNotices(data && data.content ? data.content : []);
    } catch (e) {
      setNotices([]);
    } finally {
      setLoading(false);
    }
  }, [customNotices, user]);

  useEffect(() => {
    if (customNotices) {
      setNotices(customNotices);
      setLoading(false);
    } else {
      fetchNotices();
    }
  }, [customNotices, fetchNotices, refreshTrigger]);

  const handleDeleteSuccess = (deletedId) => {
    setNotices((prev) => prev.filter((n) => n.id !== deletedId));
    setSelectedNoticeForDelete(null);
  };

  const getPriorityClass = (priority) => {
    switch (priority) {
      case 'URGENT': return 'badge-urgent';
      case 'HIGH': return 'badge-high';
      case 'MEDIUM': return 'badge-medium';
      default: return 'badge-low';
    }
  };

  const canManageNotice = (notice) => {
    if (isAdmin) return true;
    if (isTeacher && user && notice.authorId === user.id) return true;
    return false;
  };

  if (loading) {
    return (
      <div style={{ textAlign: 'center', padding: '3rem' }}>
        <p style={{ color: 'var(--text-muted)' }}>Loading notices...</p>
      </div>
    );
  }

  if (!notices || notices.length === 0) {
    return (
      <div className="card" style={{ textAlign: 'center', padding: '3rem 2rem' }}>
        <p style={{ color: 'var(--text-muted)', fontSize: '1.1rem' }}>No notices available</p>
      </div>
    );
  }

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '1.25rem' }}>
      {notices.map((notice) => (
        <div key={notice.id} className="card" style={{ borderLeft: notice.priority === 'URGENT' ? '4px solid var(--danger)' : '1px solid var(--border)' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start', flexWrap: 'wrap', gap: '0.75rem', marginBottom: '0.75rem' }}>
            <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem', flexWrap: 'wrap' }}>
              <span className={`badge ${getPriorityClass(notice.priority)}`}>
                {notice.priority}
              </span>
              <span className="badge badge-category" style={{ backgroundColor: notice.categoryColor ? `${notice.categoryColor}20` : undefined, color: notice.categoryColor }}>
                {notice.categoryName}
              </span>
              {notice.departmentName && (
                <span className="badge" style={{ backgroundColor: '#f1f5f9', color: '#475569' }}>
                  {notice.departmentName}
                </span>
              )}
            </div>

            <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>
              {notice.publishDate ? new Date(notice.publishDate).toLocaleDateString() : 'Recent'}
            </div>
          </div>

          <h3 style={{ fontSize: '1.25rem', marginBottom: '0.6rem' }}>
            <Link to={`/notices/${notice.id}`} style={{ color: 'var(--text-main)' }}>
              {notice.title}
            </Link>
          </h3>

          <p style={{ color: 'var(--text-muted)', fontSize: '0.95rem', marginBottom: '1.25rem', whiteSpace: 'pre-line' }}>
            {notice.content && notice.content.length > 220
              ? `${notice.content.substring(0, 220)}...`
              : notice.content}
          </p>

          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', flexWrap: 'wrap', gap: '1rem', paddingTop: '0.75rem', borderTop: '1px solid var(--border)' }}>
            <div style={{ fontSize: '0.85rem', color: 'var(--text-muted)' }}>
              Posted by: <strong>{notice.authorName || 'Faculty'}</strong>
            </div>

            <div style={{ display: 'flex', gap: '0.5rem' }}>
              <Link to={`/notices/${notice.id}`} className="btn btn-secondary btn-sm">
                View Details
              </Link>

              {canManageNotice(notice) && (
                <>
                  {onEdit ? (
                    <button
                      type="button"
                      className="btn btn-secondary btn-sm"
                      onClick={() => onEdit(notice)}
                    >
                      Edit
                    </button>
                  ) : (
                    <Link to={`/teacher/edit-notice/${notice.id}`} className="btn btn-secondary btn-sm">
                      Edit
                    </Link>
                  )}

                  <button
                    type="button"
                    className="btn btn-danger btn-sm"
                    onClick={() => setSelectedNoticeForDelete(notice)}
                  >
                    Delete
                  </button>
                </>
              )}
            </div>
          </div>
        </div>
      ))}

      {selectedNoticeForDelete && (
        <DeleteNotice
          noticeId={selectedNoticeForDelete.id}
          noticeTitle={selectedNoticeForDelete.title}
          onDeleteSuccess={() => handleDeleteSuccess(selectedNoticeForDelete.id)}
          onCancel={() => setSelectedNoticeForDelete(null)}
        />
      )}
    </div>
  );
};

export default ViewNotices;
